  update public.road_sections set
    geom = extensions.ST_GeomFromText('LINESTRING(-70.261246 -18.016270,-70.261719 -18.017169,-70.262322 -18.018493,-70.262383 -18.018692,-70.262402 -18.018896,-70.262345 -18.019271,-70.262228 -18.019528,-70.262045 -18.019747,-70.261166 -18.020536,-70.260830 -18.020797,-70.260555 -18.021076,-70.259801 -18.021711,-70.259309 -18.022174,-70.259263 -18.022234,-70.259279 -18.022334,-70.259489 -18.022736,-70.260336 -18.023861,-70.262898 -18.027573,-70.263818 -18.028820,-70.263983 -18.029107,-70.265774 -18.031681,-70.266034 -18.032018,-70.266191 -18.032172,-70.266361 -18.032284,-70.266638 -18.032397,-70.266769 -18.032524,-70.266820 -18.032695,-70.266822 -18.033000,-70.266920 -18.033298,-70.268193 -18.035077,-70.269157 -18.036548,-70.269482 -18.036932,-70.269690 -18.037050,-70.270224 -18.037267,-70.270376 -18.037428,-70.270420 -18.037645,-70.270344 -18.037971,-70.270353 -18.038166,-70.270382 -18.038262,-70.270573 -18.038562,-70.272093 -18.040755,-70.272750 -18.041634,-70.274605 -18.044261,-70.274761 -18.044532,-70.275689 -18.045903,-70.277484 -18.048390,-70.278659 -18.050138,-70.281370 -18.053913,-70.284220 -18.058089,-70.286383 -18.061128,-70.291882 -18.069048,-70.292297 -18.069558,-70.292940 -18.070037,-70.293232 -18.070331,-70.293295 -18.070445,-70.293417 -18.071118,-70.293549 -18.071377,-70.294047 -18.072151,-70.297671 -18.077315,-70.298161 -18.077976,-70.299463 -18.079882,-70.301989 -18.083465,-70.302730 -18.084592,-70.304290 -18.086768,-70.305344 -18.088311,-70.305618 -18.088921,-70.306051 -18.089561,-70.307965 -18.092215,-70.312751 -18.099102,-70.313504 -18.100145,-70.314274 -18.101288,-70.316965 -18.104752,-70.317976 -18.105972,-70.321804 -18.110761,-70.323538 -18.113021,-70.326551 -18.116795,-70.327027 -18.117460,-70.327723 -18.118608,-70.328202 -18.119621,-70.328588 -18.120675,-70.328837 -18.121479,-70.330367 -18.128134,-70.331080 -18.131475,-70.331382 -18.132591,-70.331735 -18.133654,-70.332514 -18.135549,-70.332738 -18.135971,-70.334496 -18.139764,-70.335108 -18